#!/usr/bin/env python3
"""The mascot of the logo as a 3D model, generated by the API of Meshy.

    MESHY_API_KEY=... python3 scripts/meshy.py [--image PNG] [--out DIR] [--dry-run]
    npm run mascot:generate

Steps (https://docs.meshy.ai/en/api/image-to-3d, https://docs.meshy.ai/en/api/rigging):
  1. Image to 3D: the logo (docs/assets/images/theplanet.png) as a data URI, a textured
     model in T-pose (easier to rig), remeshed to 30,000 triangles for the web, GLB only;
     on 2026-11-24 the model kept the walking pose of the logo all the same, and rigging
     worked (CLAUDE.md, Section 12);
  2. Rigging of that task (a biped skeleton), which also returns a walking and a running
     animation;
  3. the GLB files downloaded into DIR (build/meshy/<date>/ by default, git-ignored), with
     provenance.json: the parameters, the task identifiers, the credits used, never the key
     nor the signed download addresses.
Meshy keeps the results of the API for at most 3 days
(https://docs.meshy.ai/en/api/asset-retention): copy what is to be kept into media/mascot/
before then. On a paid plan the models belong to the customer (terms of
use, 3.2, https://www.meshy.ai/terms-of-use); the owner chose a paid plan on 2026-11-23.
The model of 2026-11-24 is kept in media/mascot/, with its README.md and provenance.json.
The key is read from the environment only (CLAUDE.md, Section 2). Cost at 2026-11: about 30
credits for Image to 3D with texture and 5 for rigging. Standard library only.
"""
from __future__ import annotations

import argparse
import base64
import datetime as dt
import hashlib
import json
import os
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Callable

ROOT = Path(__file__).resolve().parent.parent
API = "https://api.meshy.ai/openapi/v1"
IMAGE = ROOT / "docs" / "assets" / "images" / "theplanet.png"
DONE = {"SUCCEEDED"}
FAILED = {"FAILED", "CANCELED", "EXPIRED"}

# Image to 3D: what the site needs, and nothing that costs more.
IMAGE_TO_3D = {
    "ai_model": "latest",
    "should_texture": True,
    "enable_pbr": False,
    "should_remesh": True,
    "topology": "triangle",
    "target_polycount": 30000,
    "pose_mode": "t-pose",
    "target_formats": ["glb"],
    "origin_at": "bottom",
}
RIGGING = {"animation_type": "biped"}

Request = Callable[[str, str, dict | None], dict]


class MeshyError(RuntimeError):
    pass


def data_uri(path: Path) -> str:
    kind = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp"}[path.suffix.lower()]
    return f"data:{kind};base64," + base64.b64encode(path.read_bytes()).decode("ascii")


def http_client(key: str) -> Request:
    """A JSON client of the API: request(method, path, body) -> the decoded answer."""
    def request(method: str, path: str, body: dict | None = None) -> dict:
        data = json.dumps(body).encode("utf-8") if body is not None else None
        req = urllib.request.Request(
            f"{API}/{path}", data=data, method=method,
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json", "User-Agent": "thesite-meshy"},
        )
        try:
            with urllib.request.urlopen(req, timeout=120) as response:
                return json.load(response)
        except urllib.error.HTTPError as error:
            detail = error.read().decode("utf-8", errors="replace")[:300]
            raise MeshyError(f"{method} {path}: HTTP {error.code}: {detail}") from None
    return request


def wait(request: Request, path: str, *, interval: float = 10, timeout: float = 1800,
         sleep: Callable[[float], None] = time.sleep, log: Callable[[str], None] = print) -> dict:
    """Polls a task until it succeeds; raises when it fails or takes longer than timeout."""
    waited = 0.0
    while True:
        task = request("GET", path, None)
        status = task.get("status")
        if status in DONE:
            return task
        if status in FAILED:
            message = (task.get("task_error") or {}).get("message", "no message")
            raise MeshyError(f"{path}: {status}: {message}")
        if waited >= timeout:
            raise MeshyError(f"{path}: still {status} after {int(waited)} s")
        log(f"meshy: {path}: {status} {task.get('progress', 0)}%")
        sleep(interval)
        waited += interval


def download(url: str, target: Path, fetch: Callable[[str], bytes] | None = None) -> int:
    if not url:
        raise MeshyError(f"no address for {target.name}")
    if fetch is None:
        def fetch(address: str) -> bytes:
            with urllib.request.urlopen(urllib.request.Request(address, headers={"User-Agent": "thesite-meshy"}), timeout=300) as r:
                return r.read()
    data = fetch(url)
    target.write_bytes(data)
    return len(data)


def generate(request: Request, image: Path, out: Path, *, fetch: Callable[[str], bytes] | None = None,
             sleep: Callable[[float], None] = time.sleep, log: Callable[[str], None] = print) -> dict:
    """The three steps; returns the provenance, also written to out/provenance.json."""
    out.mkdir(parents=True, exist_ok=True)
    model_id = request("POST", "image-to-3d", {"image_url": data_uri(image), **IMAGE_TO_3D})["result"]
    log(f"meshy: image to 3D, task {model_id}")
    model = wait(request, f"image-to-3d/{model_id}", sleep=sleep, log=log)
    files = {"mascot.glb": download(model["model_urls"]["glb"], out / "mascot.glb", fetch)}
    if model.get("thumbnail_url"):
        files["mascot-thumbnail.png"] = download(model["thumbnail_url"], out / "mascot-thumbnail.png", fetch)

    rig_id = request("POST", "rigging", {"input_task_id": model_id, **RIGGING})["result"]
    log(f"meshy: rigging, task {rig_id}")
    rig = wait(request, f"rigging/{rig_id}", sleep=sleep, log=log)
    result = rig.get("result") or {}
    animations = result.get("basic_animations") or {}
    files["mascot-rigged.glb"] = download(result.get("rigged_character_glb_url", ""), out / "mascot-rigged.glb", fetch)
    for name in ("walking", "running"):
        if animations.get(f"{name}_glb_url"):
            files[f"mascot-{name}.glb"] = download(animations[f"{name}_glb_url"], out / f"mascot-{name}.glb", fetch)

    provenance = {
        "generated": dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds"),
        "source_image": str(image.relative_to(ROOT)) if image.is_relative_to(ROOT) else image.name,
        "source_sha256": hashlib.sha256(image.read_bytes()).hexdigest(),
        "image_to_3d": {"task": model_id, "parameters": IMAGE_TO_3D, "credits": model.get("consumed_credits")},
        "rigging": {"task": rig_id, "parameters": RIGGING, "credits": rig.get("consumed_credits")},
        "files": files,
        "documentation": ["https://docs.meshy.ai/en/api/image-to-3d", "https://docs.meshy.ai/en/api/rigging"],
    }
    (out / "provenance.json").write_text(json.dumps(provenance, indent=2) + "\n", encoding="utf-8")
    return provenance


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--image", type=Path, default=IMAGE)
    parser.add_argument("--out", type=Path, default=ROOT / "build" / "meshy" / dt.date.today().isoformat())
    parser.add_argument("--dry-run", action="store_true", help="print the requests, send nothing")
    args = parser.parse_args(argv[1:])
    if args.dry_run:
        print(json.dumps({"POST image-to-3d": {"image_url": f"data URI of {args.image}", **IMAGE_TO_3D},
                          "POST rigging": {"input_task_id": "<task of image to 3D>", **RIGGING}}, indent=2))
        return 0
    key = os.environ.get("MESHY_API_KEY", "")
    if not key:
        print("meshy: MESHY_API_KEY is not set (a secret of the Codespace, never a file)", file=sys.stderr)
        return 2
    try:
        provenance = generate(http_client(key), args.image, args.out)
    except MeshyError as error:
        print(f"meshy: {error}", file=sys.stderr)
        return 1
    print(f"meshy: {len(provenance['files'])} files in {args.out}; Meshy deletes them in 3 days")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
